def reference(vectors):
    state = 'WALK_LEFT'
    counter = 0
    result = []
    for v in vectors:
        areset = v['areset']
        bl = v['bump_left']
        br = v['bump_right']
        g = v['ground']
        d = v['dig']

        if areset:
            state = 'WALK_LEFT'
            counter = 0

        if state == 'WALK_LEFT':
            out = {'walk_left':1,'walk_right':0,'aaah':0,'digging':0}
        elif state == 'WALK_RIGHT':
            out = {'walk_left':0,'walk_right':1,'aaah':0,'digging':0}
        elif state == 'FALL_LEFT' or state == 'FALL_RIGHT':
            out = {'walk_left':0,'walk_right':0,'aaah':1,'digging':0}
        elif state == 'DIG_LEFT' or state == 'DIG_RIGHT':
            out = {'walk_left':0,'walk_right':0,'aaah':0,'digging':1}
        else:
            out = {'walk_left':0,'walk_right':0,'aaah':0,'digging':0}
        result.append(out)

        if areset:
            continue

        if state == 'WALK_LEFT':
            if g == 0:
                state = 'FALL_LEFT'
                counter = 0
            elif d == 1:
                state = 'DIG_LEFT'
            elif bl == 1 or br == 1:
                state = 'WALK_RIGHT'
        elif state == 'WALK_RIGHT':
            if g == 0:
                state = 'FALL_RIGHT'
                counter = 0
            elif d == 1:
                state = 'DIG_RIGHT'
            elif bl == 1 or br == 1:
                state = 'WALK_LEFT'
        elif state == 'FALL_LEFT':
            if g == 1:
                if counter > 20:
                    state = 'SPLAT'
                else:
                    state = 'WALK_LEFT'
                counter = 0
            else:
                counter = counter + 1
        elif state == 'FALL_RIGHT':
            if g == 1:
                if counter > 20:
                    state = 'SPLAT'
                else:
                    state = 'WALK_RIGHT'
                counter = 0
            else:
                counter = counter + 1
        elif state == 'DIG_LEFT':
            if g == 0:
                state = 'FALL_LEFT'
                counter = 0
        elif state == 'DIG_RIGHT':
            if g == 0:
                state = 'FALL_RIGHT'
                counter = 0
    return result
```

